/*
 * THE COURSE'S CONCEPTS, FOR A COACH CHOOSING A PATH (TASK-L184 §3).
 *
 * Every concept's id and title, and nothing about any person. Alphabetical by
 * title: `Concept` holds no order of its own and the backend promises none for
 * a query (L170 measured file order lying), and a coach choosing by hand reads
 * a list they can scan. The path's ORDER is the coach's, set on the page.
 * It runs when the request's caller arrives (`userId`), once per call.
 */
if (Inputs.userId !== undefined) (async () => {
  try {
    const rows = await Noodl.Records.query('Concept', {}, { limit: 1000, plain: true });
    Outputs.concepts = rows
      .map((r) => ({ conceptId: String(r.conceptId), title: String(r.title || r.conceptId) }))
      .sort((a, b) => a.title.localeCompare(b.title));
    Outputs.done();
  } catch (e) {
    console.error('[dbt:conceptList] ' + String((e && e.message) || e));
    Outputs.failed();
  }
})();
